Then, for a fixed number of arm pulls $N_t(a) \in \NN$ of arm $a$ with $\mu_a > \xi$, the optimal growth rate of the e-process under the worst-case instance is
\begin{align}\label{eq:minmax_e_power}
    &\inf_{P \in \Pcal(\mu_a)} \sup_{E = (E_t)_{t \in \NN}} \frac{\EE[\log(E_t)]}{N_t(a)} 
    \\ \quad &= \log\frac{1-\mu_a}{1-\xi} + \mu_a \log\frac{\mu_a(1-\xi)}{\xi(1-\mu_a)}.
\end{align}

For any $\delta$-correct fixed confidence GAI algorithm $(\pi, \tau)$, the asymptotic minimax stopping time $\tau_{\text{stop}}$ is lower bounded by:
    \begin{align}
        \liminf_{\delta \rightarrow 0 \ (\pi, \tau)}\sup_{P \in \Pcal(\bm\mu)}\frac{\EE[\tau_{\text{stop}}]}{\log(1/\delta)} \geq \sum_{a=1}^K \frac{1}{d(\mu_a, \xi)}.
    \end{align}

For $m \in [\Gcal_{\bm\mu},K]$, Algorithm \ref{alg:i-GAI} achieves the minimax lower bound for $\tau_{\text{stop}}$, i.e.,  
    \begin{equation}
        \lim_{\delta \rightarrow 0}\sup_{P \in \Pcal(\bm\mu)} \frac{\EE[\tau_{\text{stop}}]}{\log(1/\delta)} \leq \sum_{a=1}^K \frac{1}{d(\mu_a, \xi)}.
    \end{equation}

For all $i \leq G_{\bm\mu}$, the asymptotic minimax lower bound on the stopping time $\tau_{\Gcal, i}$ is given by:
    \begin{align}\label{eq:min_max_good_bound}
        \liminf_{\delta \rightarrow 0 \ (\pi, \tau)}\sup_{P \in \Pcal(\bm\mu)} \frac{\EE[\tau_{\Gcal, i}]}{\log(1/\delta)} \geq 
        \quad \sum_{a: \mu_a \geq \mu_{i^*}} \frac{1}{d(\mu_a, \xi)}.
    \end{align}

For all $m \in [K]$, $i \leq \min(m, \Gcal_{\bm\mu})$, our modified version of Algorithm \ref{alg:i-GAI} achieves the minimax lower bound for $\tau_{\Gcal, i}$, i.e.,
    \begin{equation}\label{eq:min_max_good}
        \lim_{\delta \rightarrow 0}\sup_{P \in \Pcal(\bm\mu)} \frac{\EE[\tau_{\Gcal, i}]}{\log(1/\delta)} \leq \sum_{a:\mu_a \geq \mu_{i^*}}\frac{1}{d(\mu_a, \xi)}.
    \end{equation}
